export type RetryOptions = {
  /** How many times to try in all. */
  attempts: number;
  /** Delay before the first retry, in milliseconds. */
  delayMs: number;
  /** Multiply the delay by this after each failure. */
  factor?: number;
  /** Give up once this many milliseconds have passed since the first try. */
  deadlineMs?: number;
};

export class RetryError extends Error {
  constructor(
    message: string,
    readonly tries: number,
    readonly last: unknown,
  ) {
    super(message);
  }
}

const sleep = (ms: number) => new Promise((resolve) => setTimeout(resolve, ms));

export async function retry<T>(fn: () => Promise<T>, options: RetryOptions): Promise<T> {
  const started = Date.now();
  let delay = options.delayMs;
  let last: unknown;
  for (let tries = 0; tries <= options.attempts; tries++) {
    try {
      return await fn();
    } catch (error) {
      last = error;
      if (options.deadlineMs && Date.now() - started > options.deadlineMs) {
        throw new RetryError("deadline passed", tries, last);
      }
      await sleep(delay);
      delay = delay * (options.factor ?? 2);
    }
  }
  throw new RetryError(`gave up after ${options.attempts} tries`, options.attempts, last);
}
import { expect, test } from "bun:test";
import { retry, RetryError } from "./retry";

test("returns the first success", async () => {
  let calls = 0;
  const value = await retry(async () => {
    calls++;
    if (calls < 2) throw new Error("flaky");
    return "ok";
  }, { attempts: 3, delayMs: 10 });
  expect(value).toBe("ok");
  expect(calls).toBe(2);
});

test("tries exactly `attempts` times", async () => {
  let calls = 0;
  await expect(
    retry(async () => {
      calls++;
      throw new Error("down");
    }, { attempts: 3, delayMs: 10 }),
  ).rejects.toBeInstanceOf(RetryError);
  expect(calls).toBe(3);
});

test("backs off by the factor", async () => {
  const delays: number[] = [];
  let last = Date.now();
  await retry(async () => {
    const now = Date.now();
    delays.push(now - last);
    last = now;
    if (delays.length < 4) throw new Error("again");
    return true;
  }, { attempts: 5, delayMs: 100, factor: 3 });
  // 100, 300, 900: this test sleeps for 1.3 seconds of real time.
  expect(delays[3]).toBeGreaterThanOrEqual(900);
});

test("stops at the deadline", async () => {
  let calls = 0;
  await expect(
    retry(async () => {
      calls++;
      throw new Error("slow");
    }, { attempts: 10, delayMs: 200, deadlineMs: 500 }),
  ).rejects.toThrow("deadline passed");
  expect(calls).toBeLessThanOrEqual(3);
});
{
  "name": "retrykit",
  "version": "0.1.0",
  "type": "module",
  "scripts": {
    "test": "bun test"
  }
}
